// Characterization harness: runs identical scenarios against two implementations
// of src/notifications and asserts every observable outcome is identical.
// Usage: node compare.js <origDir> <newDir>
const assert = require('node:assert/strict');
const path = require('node:path');

const [origDir, newDir] = process.argv.slice(2);
const impls = {
  orig: require(path.resolve(origDir, 'index.js')),
  next: require(path.resolve(newDir, 'index.js'))
};

const CHANNELS = ['email', 'sms', 'slack', 'inapp'];
const BASE_TIME = Date.parse('2026-01-02T03:04:05.000Z');

function clone(value) {
  return value === undefined ? undefined : JSON.parse(JSON.stringify(value));
}

// Environment with a counting clock so any change in the number or order of
// now() calls shows up in ids, timestamps, and expiry values.
function makeEnv({ step = 1000, transport = 'full' } = {}) {
  const log = [];
  const clock = { t: BASE_TIME, calls: 0, step };
  const now = () => {
    clock.calls += 1;
    return new Date(clock.t + clock.calls * clock.step);
  };
  const full = {};
  for (const ch of CHANNELS) {
    full[ch] = async function (payload) {
      log.push([ch, this === full, clone(payload), Object.keys(payload)]);
      return 'ignored-return';
    };
  }
  let t;
  if (transport === 'full') t = full;
  else if (transport === 'none') t = undefined;
  else if (transport === 'empty') t = {};
  else if (transport === 'nonfn') t = { email: 'x', sms: 1, slack: {}, inapp: null };
  else if (transport === 'reject') {
    t = {};
    for (const ch of CHANNELS) t[ch] = async () => { throw new Error(`${ch} boom`); };
  }
  return { log, clock, now, transport: t, store: new Map() };
}

function snapStore(store) {
  return [...store.entries()].map(([k, v]) => [k, [...v]]);
}

async function attempt(fn) {
  try {
    const value = await fn();
    return { ok: clone(value), keys: value && typeof value === 'object' ? Object.keys(value) : null };
  } catch (err) {
    return { error: { name: err.name, ctor: err.constructor.name, message: err.message } };
  }
}

function attemptSync(fn) {
  try {
    const value = fn();
    return { ok: clone(value), keys: value && typeof value === 'object' ? Object.keys(value) : null };
  } catch (err) {
    return { error: { name: err.name, ctor: err.constructor.name, message: err.message } };
  }
}

const USERS = [
  null,
  undefined,
  'str',
  42,
  {},
  { id: '' },
  { id: 0 },
  { id: 'u1', name: 'Ava', email: 'ava@example.com', emailOptIn: true },
  { id: 'u1b', email: 'ava@example.com', emailOptIn: false },
  { id: 'u1c', name: 'Ava', email: 'no-at-sign' },
  { id: 'u 1/&?=x', name: 'Q', email: 'q@example.com', locale: 'fr-FR' },
  { id: 'u2', name: 'Bo', phone: '+15551234567', smsOptIn: true },
  { id: 'u2b', phone: '+15551234567', smsOptIn: false },
  { id: 'u2c', phone: '555-1212' },
  { id: 'u2d', phone: '+0123456789' },
  { id: 'u2e', phone: '+1234567' },
  { id: 'u3', name: 'Cy', slackId: 'U123' },
  { id: 'u3b', slackChannel: '#alerts', slackWorkspace: 'eng' },
  { id: 'u3c', slackId: 'U9', slackChannel: '#c' },
  { id: 'u4', name: 'Dee' },
  { id: 'u4b', disabledInApp: true, email: 'd@example.com' },
  {
    id: 'all',
    name: 'Everything',
    email: 'all@example.com',
    phone: '+447700900123',
    slackId: 'UALL',
    slackChannel: '#all',
    slackWorkspace: 'ws',
    locale: 'ja-JP',
    emailOptIn: true,
    smsOptIn: true
  },
  {
    id: 'all-optout',
    email: 'all@example.com',
    phone: '+447700900123',
    slackId: 'UALL',
    emailOptIn: false,
    smsOptIn: false
  }
];

const MESSAGES = [
  null,
  'str',
  {},
  { title: 'T' },
  { body: 'B' },
  { title: '', body: 'B' },
  { title: 'Hello {{name}} {{name}}', body: 'Your {{category}} for {{id}} {{id}}' },
  { title: 'Deal', body: 'Save now', category: 'marketing' },
  { title: 'Deal', body: 'Save now', category: 'marketing', priority: 'urgent' },
  { title: 'Login', body: '<script>alert("x")</script> & \'q\'', category: 'security' },
  { title: 'Receipt', body: 'Paid', category: 'transactional', priority: 'normal' },
  { title: 'Deploy', body: 'Finished', category: 'release', icon: 'rocket', actionUrl: '/deploys' },
  { title: 'A'.repeat(20), body: 'B'.repeat(40), priority: 'urgent', category: 'transactional' },
  { title: 'X'.repeat(60), body: 'Y'.repeat(200), category: 'general' },
  // Composed SMS text is exactly 140 chars: 67 + ' - ' + 70.
  { title: 'T'.repeat(67), body: 'b'.repeat(70) },
  { title: 'T'.repeat(67), body: 'b'.repeat(71) },
  { title: 123, body: 456, priority: 'low' }
];

const SEND_OPTIONS = [
  undefined,
  {},
  { force: true },
  { locale: 'de-DE' },
  { threadTs: '171234.0001', channel: '#ops' },
  { channel: '#only-channel' },
  { actionUrl: '/security', expiresInHours: 5 },
  null
];

const CTOR_VARIANTS = [
  () => ({}),
  () => ({
    from: 'alerts@example.com',
    replyTo: 'help@example.com',
    unsubscribeBaseUrl: 'https://u.example/x',
    senderId: 'ACME',
    segmentLength: 40,
    defaultWorkspace: 'product',
    defaultChannel: '#announce',
    defaultIcon: 'star',
    defaultAction: '/inbox',
    defaultLocale: 'es-ES',
    defaultSender: 'Someone',
    templates: { a: 1 },
    channel: 'bogus-channel-override'
  }),
  () => ({ maxPerHour: 0, segmentLength: 0 })
];

// Each scenario receives a library and returns a serializable trace.
const scenarios = [];

// 1. Cross product of single sends on a fresh notifier.
for (const channel of CHANNELS) {
  CTOR_VARIANTS.forEach((ctor, ci) => {
    USERS.forEach((user, ui) => {
      MESSAGES.forEach((message, mi) => {
        SEND_OPTIONS.forEach((sendOptions, si) => {
          scenarios.push({
            name: `send ${channel} ctor${ci} user${ui} msg${mi} opts${si}`,
            run: async lib => {
              const env = makeEnv();
              const n = lib.createNotifier(channel, {
                ...ctor(),
                transport: env.transport,
                throttleStore: env.store,
                now: env.now
              });
              const args = sendOptions === undefined ? [user, message] : [user, message, sendOptions];
              const result = await attempt(() => n.send(...args));
              return { result, log: env.log, store: snapStore(env.store), calls: env.clock.calls, channel: n.channel };
            }
          });
        });
      });
    });
  });
}

// 2. Throttling sequences with a frozen clock that can be advanced manually.
const THROTTLE_MESSAGES = [
  { title: 'One', body: 'Two', category: 'general' },
  { title: 'One', body: 'Two' },
  { title: 'Sec', body: 'x', category: 'security' },
  { title: 'Urg', body: 'x', priority: 'urgent' },
  { title: 'Mk', body: 'x', category: 'marketing' }
];
const THROTTLE_OPTIONS = [undefined, { force: true }, { threadTs: '1.1' }];
for (const channel of CHANNELS) {
  for (const maxPerHour of [undefined, 1, 2]) {
    THROTTLE_MESSAGES.forEach((message, mi) => {
      THROTTLE_OPTIONS.forEach((sendOptions, oi) => {
        scenarios.push({
          name: `throttle ${channel} max${maxPerHour} msg${mi} opts${oi}`,
          run: async lib => {
            const env = makeEnv({ step: 0 });
            const user = USERS[21];
            const n = lib.createNotifier(channel, {
              transport: env.transport,
              throttleStore: env.store,
              now: env.now,
              maxPerHour
            });
            const results = [];
            const send = () => (sendOptions === undefined ? n.send(user, message) : n.send(user, message, sendOptions));
            for (let i = 0; i < 55; i += 1) {
              if (i === 3) env.clock.t += 30 * 60 * 1000;
              if (i === 5) env.clock.t += 31 * 60 * 1000;
              if (i === 6) env.clock.t += 60 * 60 * 1000 - 1;
              results.push(await attempt(send));
            }
            // A different category must use its own bucket.
            results.push(await attempt(() => n.send(user, { ...message, category: 'other' })));
            return { results, log: env.log, store: snapStore(env.store), calls: env.clock.calls };
          }
        });
      });
    });
  }
}

// 3. createAllNotifiers with a shared store and options.
for (const withArgs of [true, false]) {
  scenarios.push({
    name: `createAllNotifiers args=${withArgs}`,
    run: async lib => {
      const env = makeEnv();
      const all = withArgs
        ? lib.createAllNotifiers({ transport: env.transport, throttleStore: env.store, now: env.now, maxPerHour: 1 })
        : lib.createAllNotifiers();
      const trace = { keys: Object.keys(all), channels: Object.values(all).map(n => n.channel), results: [] };
      for (const ch of Object.keys(all)) {
        for (let i = 0; i < 2; i += 1) {
          trace.results.push(await attempt(() => all[ch].send(USERS[21], { title: 't', body: 'b', category: 'c' })));
        }
      }
      if (withArgs) {
        trace.log = env.log;
        trace.store = snapStore(env.store);
        trace.calls = env.clock.calls;
      }
      return trace;
    }
  });
}

// 4. Transport failure modes.
for (const channel of CHANNELS) {
  for (const transport of ['none', 'empty', 'nonfn', 'reject']) {
    scenarios.push({
      name: `transport ${channel} ${transport}`,
      run: async lib => {
        const env = makeEnv({ transport });
        const n = lib.createNotifier(channel, { transport: env.transport, throttleStore: env.store, now: env.now });
        const first = await attempt(() => n.send(USERS[21], { title: 't', body: 'b' }));
        const direct = await attempt(() => n.deliver({ any: 'payload' }));
        return { first, direct, store: snapStore(env.store), calls: env.clock.calls };
      }
    });
  }
  scenarios.push({
    name: `no options ${channel}`,
    run: async lib => {
      const n = lib.createNotifier(channel);
      return { channel: n.channel, result: await attempt(() => n.send(USERS[21], { title: 't', body: 'b' })) };
    }
  });
}

// 5. Direct calls to the pipeline steps exposed on the notifier.
for (const channel of CHANNELS) {
  USERS.forEach((user, ui) => {
    MESSAGES.forEach((message, mi) => {
      SEND_OPTIONS.forEach((sendOptions, si) => {
        scenarios.push({
          name: `methods ${channel} user${ui} msg${mi} opts${si}`,
          run: async lib => {
            const env = makeEnv();
            const n = lib.createNotifier(channel, {
              transport: env.transport,
              throttleStore: env.store,
              now: env.now,
              segmentLength: 50
            });
            const args = sendOptions === undefined ? [user, message] : [user, message, sendOptions];
            return {
              validateUser: attemptSync(() => n.validateUser(user)),
              validateMessage: attemptSync(() => n.validateMessage(message)),
              shouldThrottle: attemptSync(() => n.shouldThrottle(...args)),
              format: attemptSync(() => n.format(...args)),
              recordDelivery: attemptSync(() => n.recordDelivery(user, message)),
              shouldThrottleAfter: attemptSync(() => n.shouldThrottle(...args)),
              deliver: await attempt(() => n.deliver({ direct: true })),
              log: env.log,
              store: snapStore(env.store),
              calls: env.clock.calls
            };
          }
        });
      });
    });
  });
}

// 6. Factory surface.
scenarios.push({
  name: 'factory surface',
  run: async lib => {
    const trace = {
      exports: Object.keys(lib).sort(),
      registryKeys: Object.keys(lib.registry),
      registryTypes: Object.values(lib.registry).map(v => typeof v),
      unknown: ['fax', '', undefined, null, 'Email', 'EMAIL'].map(ch => attemptSync(() => lib.createNotifier(ch)))
    };
    // `new registry[channel](options)` was the only way to use registry entries before.
    trace.viaNew = [];
    for (const ch of CHANNELS) {
      const env = makeEnv();
      const n = new lib.registry[ch]({ transport: env.transport, throttleStore: env.store, now: env.now });
      trace.viaNew.push({ channel: n.channel, result: await attempt(() => n.send(USERS[21], { title: 't', body: 'b' })), log: env.log });
    }
    return trace;
  }
});

async function main() {
  let failures = 0;
  for (const scenario of scenarios) {
    const a = await scenario.run(impls.orig);
    const b = await scenario.run(impls.next);
    try {
      assert.deepStrictEqual(b, a);
      // deepStrictEqual ignores key order; payload key order is observable via JSON.
      assert.equal(JSON.stringify(b), JSON.stringify(a));
    } catch (err) {
      failures += 1;
      if (failures <= 5) {
        console.error(`MISMATCH: ${scenario.name}\n${err.message.slice(0, 3000)}\n`);
      }
    }
  }
  console.log(`${scenarios.length} scenarios, ${failures} mismatches`);
  process.exitCode = failures ? 1 : 0;
}

main();

