const createRateLimiter = require('./rateLimiter');

function validateRecipient(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

/**
 * Composes the shared send pipeline with a channel strategy.
 *
 * `createChannel(options, { now })` must return:
 *   name               channel id used in payload ids, results, and throttle keys
 *   defaultMaxPerHour  hourly limit used when options.maxPerHour is not set
 *   validateUser(user)                                       checks beyond user.id
 *   shouldThrottle(rateLimiter, user, message, sendOptions)  throttle policy
 *   format(base, user, message, sendOptions)                 channel payload from the base payload
 *   deliver(transport, payload)                              hands the payload to the transport
 */
function createChannelNotifier(createChannel, options = {}) {
  const transport = options.transport || {};
  const now = options.now || (() => new Date());
  const defaultLocale = options.defaultLocale || 'en-US';
  const channel = createChannel(options, { now });
  const rateLimiter = createRateLimiter({
    channel: channel.name,
    store: options.throttleStore || new Map(),
    maxPerHour: options.maxPerHour || channel.defaultMaxPerHour,
    now
  });

  function validateUser(user) {
    validateRecipient(user);
    channel.validateUser(user);
  }

  function shouldThrottle(user, message, sendOptions = {}) {
    return channel.shouldThrottle(rateLimiter, user, message, sendOptions);
  }

  function format(user, message, sendOptions = {}) {
