function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function createEmailChannel(options) {
  const from = options.from || 'noreply@example.com';
  const replyTo = options.replyTo || 'support@example.com';
  const unsubscribeBaseUrl = options.unsubscribeBaseUrl || 'https://example.com/unsubscribe';

  function footerFor(user, message) {
    if (message.category === 'transactional' || message.category === 'security') {
      return `Sent to ${user.email} because of recent account activity.`;
    }
    const url = `${unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
    return `You can unsubscribe at ${url}.`;
  }

  return {
    name: 'email',
    defaultMaxPerHour: 8,

    validateUser(user) {
      if (!user.email || !user.email.includes('@')) {
        throw new TypeError('user.email is required for email notifications');
      }
    },

    shouldThrottle(rateLimiter, user, message, sendOptions) {
      const limit = rateLimiter.check(user, message, sendOptions);
      if (limit.throttled) {
        return limit;
      }

      if (message.category === 'marketing' && !user.emailOptIn) {
        return {
          throttled: true,
          reason: 'user has not opted into marketing email',
          retryAt: null
        };
      }

      return { throttled: false };
    },

    format(base, user, message) {
      const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
      const footer = footerFor(user, message);

      return {
        ...base,
        to: user.email,
        from,
        replyTo,
        subject: `${subjectPrefix}${base.title}`,
        text: `${base.body}\n\n${footer}`,
        html: `<h1>${escapeHtml(base.title)}</h1><p>${escapeHtml(base.body)}</p><footer>${escapeHtml(footer)}</footer>`,
        preview: base.body.slice(0, 90)
      };
    },

    async deliver(transport, payload) {
      if (typeof transport.email !== 'function') {
        throw new Error('email transport is not configured');
      }
      await transport.email(payload);
    }
  };
}

module.exports = createEmailChannel;

