function createSmsChannel(options) {
  const senderId = options.senderId || 'APP';
  const segmentLength = options.segmentLength || 140;

  function truncate(value) {
    if (value.length <= segmentLength) {
      return value;
    }
    return `${value.slice(0, segmentLength - 1)}…`;
  }

  return {
    name: 'sms',
    defaultMaxPerHour: 4,

    validateUser(user) {
      if (!user.phone || !/^\+[1-9]\d{6,14}$/.test(user.phone)) {
        throw new TypeError('user.phone must be E.164 for SMS notifications');
      }
    },

    shouldThrottle(rateLimiter, user, message, sendOptions) {
      const limit = rateLimiter.check(user, message, sendOptions);
      if (limit.throttled) {
        return limit;
      }

      if (message.category === 'marketing' && !user.smsOptIn) {
        return {
          throttled: true,
          reason: 'user has not opted into marketing SMS',
          retryAt: null
        };
      }

      return { throttled: false };
    },

    format(base, user, message) {
      const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
      const composed = `${prefix}${base.title} - ${base.body}`;
      const text = truncate(composed);

      return {
        ...base,
        to: user.phone,
        from: senderId,
        text,
        segments: Math.ceil(text.length / segmentLength),
        preview: text
      };
    },

    async deliver(transport, payload) {
      if (typeof transport.sms !== 'function') {
        throw new Error('sms transport is not configured');
      }
      await transport.sms(payload);
    }
  };
}

module.exports = createSmsChannel;

