const createChannelNotifier = require('./createChannelNotifier');
const createEmailChannel = require('./emailChannel');
const createSmsChannel = require('./smsChannel');
const createSlackChannel = require('./slackChannel');
const createInAppChannel = require('./inAppChannel');

// Registry entries are regular functions, not arrows, so callers that still use
// `new registry[channel](options)` from when these were classes keep working.
function notifierFactory(createChannel) {
  return function createChannelSpecificNotifier(options) {
    return createChannelNotifier(createChannel, options);
  };
}

const registry = {
  email: notifierFactory(createEmailChannel),
  sms: notifierFactory(createSmsChannel),
  slack: notifierFactory(createSlackChannel),
  inapp: notifierFactory(createInAppChannel)
};

function createNotifier(channel, options = {}) {
  const factory = registry[channel];
  if (!factory) {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return factory(options);
}

function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};

